#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_camada3_site.py -- vitrine separa Shopee x Amazon (toggle + selo por
# card + placeholder pros cards Amazon). So aditivo: com so-Shopee o site fica
# igual. Roda de dentro de ~/jarvis. Depois: rode o deploy_site.py.
import sys, base64, shutil, py_compile
from pathlib import Path
d=lambda s: base64.b64decode(s).decode("utf-8")
# tenta os dois caminhos (pacote da VPS e raiz)
cands=[Path("creative_engine/bio_page_builder.py"),Path("bio_page_builder.py")]
ALVO=next((c for c in cands if c.exists()),None)
JOBS=[(ALVO,"filtro-plat",[(d(""),d("")),(d(""),d("")),(d(""),d("")),(d(""),d("")),(d(""),d("")),(d(""),d("")),(d(""),d("")),(d(""),d(""))])] if ALVO else []
def main():
    if not ALVO: print("ABORTADO: bio_page_builder.py nao encontrado"); return 2
    rc=0
    for alvo,marca,reps in JOBS:
        s=alvo.read_text(encoding="utf-8").replace("\r\n","\n")
        if marca in s: print("JA APLICADO:",alvo); continue
        if any(o not in s for o,_ in reps): print("ABORTADO (bloco diferente):",alvo); rc=2; continue
        bak=alvo.with_suffix(alvo.suffix+".bak_camada3"); shutil.copy2(alvo,bak)
        for o,n in reps: s=s.replace(o,n,1)
        alvo.write_text(s,encoding="utf-8")
        try: py_compile.compile(str(alvo),doraise=True); print("OK:",alvo,"(backup:",bak.name,")")
        except Exception as ex: shutil.copy2(bak,alvo); print("ERRO->restaurei:",alvo,ex); rc=4
    return rc
if __name__=="__main__": sys.exit(main())
